// ===== SETTINGS: edit these =====
const SETTINGS = {
  approverEmail: 'you@example.com', // where the daily draft is sent
  fromEmail: 'you@example.com',     // must be allowed by your SMTP account
  author: 'a member of the team at Rural Root Cloud that builds RootEd',
  siteUrl: 'https://rooted.ruralrootcloud.com/',
};

// ===== What Claude knows about RootEd (taken from the website) =====
const BRIEF = `
RootEd is a school management platform built by Rural Root Cloud Tech Services And Training (India).
Tagline: "Run your school, college or coaching center — not five spreadsheets."
Who it's for: schools, colleges, and coaching/tuition centres.

Modules (five, all connected, one dataset per school):
- Academics: attendance (mark a class in one tap), grades, timetable, report cards, academic years — one record per student, not a spreadsheet per teacher.
- Staff: staff directory, leave requests with approval chains, salary/payroll — not a WhatsApp group and a register.
- Fee: fee structures, collection, Razorpay online payments and receipts — parents pay online, it reconciles automatically.
- Expense: expense entries with approval chains and auto-escalation, plus budgets — every rupee spent has a paper trail.
- Inventory: stock tracking, depreciation, overdue-return alerts — know what the school owns and where it went.

Why it's different:
- A dashboard for every role (principal, teacher, accountant, librarian, admin), enforced by role-based access control — a librarian can't see payroll, a teacher can't see budgets.
- Multi-tenant: each school gets its own subdomain, branding and data; a growing group can onboard new campuses in minutes.
- English, Hindi, or a merged Hindi+English interface — built for how staff actually read.
- Approval workflows for leave, expense and purchase requests with auto-escalation — nothing sits forgotten.

Security:
- Tenant isolation enforced at the database layer — a bug can't leak another school's data.
- Staff government ID, bank account and salary fields encrypted with AES-256-GCM, with a separate key per school.
- Immutable audit log: every change to sensitive records stored as a before/after diff that can't be edited.
- Only essential cookies; no advertising or tracking cookies.

Pricing: the core system (attendance, fees, staff, inventory) is free forever — no trial, no expiry, no credit card, unlimited staff and students.
Premium add-ons: dedicated branded email, WhatsApp alerts to parents, SMS alerts, a dedicated payment gateway in the school's name.

Onboarding: a quick call to understand classes, sections, staff and fee structure -> they map the school onto RootEd -> tenant provisioned, live and free from day one -> ongoing training and support, not a one-time handoff.

Company: Rural Root Cloud designs, builds and maintains digital products and runs practical tech training.
Belief: "World-class technology can grow from anywhere — including rural roots."
Values: reliability first, cloud-native, teach rather than hide complexity, from rural to global.
`.trim();

// One angle per day, rotating, so posts don't repeat themselves
const ANGLES = [
  'The pain of running a school on spreadsheets, registers and WhatsApp groups — and what changes with one connected system',
  'Spotlight: attendance and report cards (Academics module)',
  'Spotlight: online fee collection with Razorpay and automatic reconciliation',
  'Spotlight: staff leave approvals and payroll in one place',
  'Spotlight: expense approvals, auto-escalation and budgets — every rupee has a paper trail',
  'Spotlight: inventory tracking and overdue-return alerts',
  'Why school data needs bank-grade protection: tenant isolation at the database layer',
  'Encrypted staff PII with a separate key per school — explained simply for a principal',
  'The immutable audit log: always being able to answer "who changed this, and when?"',
  'Software in Hindi, English, or both — building for how staff actually read',
  'The core is free forever, with no trial and no credit card — why we chose that',
  'One dashboard per role: what a principal, a teacher and an accountant each see',
  'Building world-class technology from rural roots — the mission behind RootEd',
  'From first call to going live: what onboarding a school actually looks like',
  'RootEd for coaching and tuition centres, not just schools',
  'Premium add-ons: WhatsApp and SMS alerts that reach parents where they already are',
  'A practical tip for school administrators about running admin work better, with a light mention of RootEd',
];
const FORMATS = [
  'a short story or scenario from a typical school day',
  'a numbered list of 3-5 crisp points',
  'a myth vs. reality contrast',
  'a question to school leaders followed by an answer',
  'a before/after comparison',
  'a lesson learned while building the product',
  'a direct, confident explainer',
];

const now = new Date();
const dayIndex = Math.floor(now.getTime() / 86400000);
const angle = ANGLES[dayIndex % ANGLES.length];
const format = FORMATS[dayIndex % FORMATS.length];

const staticData = $getWorkflowStaticData('global');
const history = (staticData.history || []).slice(-14);
const historyText = history.length
  ? history.map(h => `- ${h.date}: [${h.angle}] opened with "${h.hook}"`).join('\n')
  : '(none yet)';

const system = `You write LinkedIn posts for ${SETTINGS.author}, posted from their personal LinkedIn profile, to promote RootEd.

Product brief — the only source of facts you may use:
<brief>
${BRIEF}
</brief>

How to write:
- Audience: school owners, principals, administrators and coaching-centre founders, mostly in India.
- Voice: first person, warm, practical and confident; a builder talking to peers, not an advertisement.
- Length: 120-220 words. First line is a hook of at most 12 words that makes people tap "see more".
- Short paragraphs of 1-2 lines with blank lines between them. Plain text only: LinkedIn does not render markdown, so no asterisks, no headings, no bold.
- At most two emoji, only if they add something.
- End with a soft call to action and the link ${SETTINGS.siteUrl} on its own line, then 3-5 relevant hashtags on the last line.
- Never invent statistics, customer names, testimonials, partnerships, awards or features that are not in the brief. If a point needs a number the brief doesn't give, make it without the number.
- Don't reuse a hook or opening idea from the recent posts listed in the request.`;

const user = `Write today's post.

Angle: ${angle}
Format: ${format}

Recent posts (avoid repeating these openings and ideas):
${historyText}`;

const requestBody = {
  model: 'claude-opus-5-5',
  max_tokens: 16000,
  fallbacks: 'default',
  output_config: {
    effort: 'medium',
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        properties: {
          hook: { type: 'string', description: 'The first line of the post' },
          post: { type: 'string', description: 'The full post text, ready to publish' },
        },
        required: ['hook', 'post'],
        additionalProperties: false,
      },
    },
  },
  system,
  messages: [{ role: 'user', content: user }],
};

return [{ json: { settings: SETTINGS, angle, format, requestBody } }];

const res = $input.first().json;
const ctx = $('Build prompt').first().json;

if (res.stop_reason === 'refusal') {
  throw new Error('Claude declined to write this post: ' + JSON.stringify(res.stop_details));
}
if (res.stop_reason === 'max_tokens') {
  throw new Error('Claude ran out of tokens before finishing the post.');
}
const textBlock = (res.content || []).find(b => b.type === 'text');
if (!textBlock) {
  throw new Error('No text in Claude response: ' + JSON.stringify(res).slice(0, 500));
}
const draft = JSON.parse(textBlock.text);

return [{ json: { ...draft, angle: ctx.angle, settings: ctx.settings } }];

