const staticData = $getWorkflowStaticData('global');
const draft = $('Parse draft').first().json;
const history = staticData.history || [];
history.push({
  date: new Date().toISOString().slice(0, 10),
  angle: draft.angle,
  hook: draft.hook,
});
staticData.history = history.slice(-30);
return [{ json: { saved: true, historySize: staticData.history.length } }];
